class BST:
    def __init__(self):
        self.root = None

    def insert(self, x):
        if self.root is None:
            self.root = BST._Node(x)
        else:
            self.root._insert(x)

    def contains(self, x):
        return self.root is not None and self.root._contains(x)

    def inorder(self):
        result = []
        if self.root is not None:
            self.root._inorder(result)
        return result

    class _Node:
        def __init__(self, x):
            self.val = x
            self.left = None
            self.right = None

        def _insert(self, x):
            if x < self.val:
                if self.left is None:
                    self.left = BST._Node(x)
                else:
                    self.left._insert(x)
            elif x > self.val:
                if self.right is None:
                    self.right = BST._Node(x)
                else:
                    self.right._insert(x)

        def _contains(self, x):
            if x == self.val:
                return True
            elif x < self.val:
                return self.left is not None and self.left._contains(x)
            else:
                return self.right is not None and self.right._contains(x)

        def _inorder(self, result):
            if self.left is not None:
                self.left._inorder(result)
            result.append(self.val)
            if self.right is not None:
                self.right._inorder(result)
