def count_connected_components(graph):
    visited = set()
    components = 0

    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)
            for neighbor in graph.get(current, []):
                if neighbor not in visited:
                    stack.append(neighbor)

    for node in graph:
        if node not in visited:
            dfs(node)
            components += 1

    return components
