class DivisionError(Exception):
    def __init__(self, index):
        self.index = index
        super().__init__(f"Division by zero at index {index}")

def divide_all(nums, divisor):
    if divisor == 0:
        raise DivisionError(0)
    return [n / divisor for n in nums]
