def rle_decode(s):
    result = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        count_str = ''
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1
        count = int(count_str) if count_str else 1
        result.append(char * count)
    return ''.join(result)

