def flatten_dict(d, sep='.'):
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep))
            else:
                items[new_key] = v
        return items
    return _flatten(d, '', sep)
